export default {
	data() {
		return {
			selectedId: 0,
			incomeList: [
				{
					id: 0,
					name: '生活费',
					icon: 'icon-shenghuofei1'
				},
				{
					id: 1,
					name: '兼职',
					icon: 'icon-jianzhi'
				}
			
			]
		};
	},
	created() {},
	methods: {
		chooseIncome(income) {
			this.selectedId = income.id;
			this.$emit('chooseIncome', income);
		}
	}
};
